// --- M1-20 -------------------------------------------------------------------------------------
const answerOf = (
  input: Record<string, unknown>,
  vhost: FakeVhost,
  options: FakeOptions = {},
) =>
  runQuery(
    routingDlxSources,
    createRoutingDlxSourcesAction,
    { vhost: '/', ...input },
    { ...options, vhosts: { '/': vhost } },
  );

/** A queue as an older broker with statistics off lists it: no policy fields at all. */
const withoutStats = (queue: FakeQueue): FakeQueue =>
  Object.fromEntries(
    Object.entries(queue).filter(
      ([key]) => key !== 'policy' && key !== 'operator_policy',
    ),
  ) as unknown as FakeQueue;

const codes = (output: { unknownReasons: readonly { code: string }[] }) =>
  output.unknownReasons.map((reason) => reason.code);

describe('M1-20 AC-7 incomplete is never read as no hazard (A-2)', () => {
  it('returns the source with its own limit, and complete, for a healthy vhost', async () => {
    const { output } = await answerOf({ queue: 'orders.dlq' }, SAMPLE_VHOST);

    expect(output.sources).toEqual([
      {
        queue: 'orders.q',
        limit: { kind: 'finite', value: 20 },
        certainty: 'definite',
        via: ['orders.dlx'],
        reasons: expect.any(Array) as unknown[],
      },
    ]);
    expect(output.complete).toBe(true);
    expect(output.unknownReasons).toEqual([]);
    expect(output.gaps).toEqual([]);
  });

  it('says "no hazard" only for an empty list that is complete', async () => {
    const { output } = await answerOf({ queue: 'orders.q' }, SAMPLE_VHOST);

    expect(output.sources).toEqual([]);
    expect(output.complete).toBe(true);
  });

  it('keeps the pair and adds no verdict of its own', async () => {
    const { output } = await answerOf({ queue: 'orders.q' }, SAMPLE_VHOST);

    expect(Object.keys(output).sort()).toEqual(
      [
        'complete',
        'gaps',
        'heldDeathSourcesConsidered',
        'queue',
        'snapshot',
        'sources',
        'sourcesMore',
        'truncation',
        'unknownReasons',
        'unknownReasonsMore',
        'vhost',
      ].sort(),
    );
  });

  it('is incomplete, with an empty list, when the broker did not send the stat fields', async () => {
    const { output } = await answerOf(
      { queue: 'orders.q' },
      {
        ...SAMPLE_VHOST,
        queues: (SAMPLE_VHOST.queues ?? []).map(withoutStats),
      },
    );

    expect(output.sources).toEqual([]);
    expect(output.complete).toBe(false);
    expect(codes(output)).toEqual(['stats-fields-missing']);
    expect(output.gaps).toContain('stats-fields-missing');
  });

  it('is incomplete when the user policies cannot be read', async () => {
    const { output } = await answerOf(
      { queue: 'orders.dlq' },
      { ...SAMPLE_VHOST, policies: 'forbidden' },
    );

    expect(output.complete).toBe(false);
    expect(codes(output)).toContain('policy-unreadable');
    // The setting of the source is unknown too, and the source is listed as a possible one.
    expect(codes(output)).toContain('dead-letter-unknown');
    expect(output.sources.map((s) => [s.queue, s.certainty])).toContainEqual([
      'orders.q',
      'possible',
    ]);
  });

  it('is incomplete when the operator policies cannot be read', async () => {
    const { output } = await answerOf(
      { queue: 'orders.dlq' },
      { ...SAMPLE_VHOST, operatorPolicies: 'method-not-allowed' },
    );

    expect(output.complete).toBe(false);
    expect(codes(output)).toContain('operator-policy-unreadable');
  });

  it('is incomplete when the principal can neither administer nor monitor', async () => {
    const { output } = await answerOf({ queue: 'orders.dlq' }, SAMPLE_VHOST, {
      profile: {
        identity: {
          user: 'app',
          tags: ['management'],
          isAdmin: false,
          canMonitor: false,
          isPolicymaker: false,
        },
      },
    });

    expect(output.complete).toBe(false);
    expect(codes(output)).toEqual(['other-clients-may-declare']);
    expect(output.sources.map((s) => s.queue)).toEqual(['orders.q']);
  });

  it('is incomplete when the vhost was read only in part', async () => {
    const { output } = await answerOf({ queue: 'orders.q' }, SAMPLE_VHOST, {
      limits: { maxQueues: 1 },
    });

    expect(output.complete).toBe(false);
    expect(output.unknownReasons).toContainEqual({
      code: 'truncated',
      subject: 'snapshot',
    });
  });

  it('says a queue that the vhost does not have is not found', async () => {
    await expect(
      answerOf({ queue: 'nope' }, SAMPLE_VHOST),
    ).rejects.toMatchObject({
      code: 'NOT_FOUND',
    });
  });

  it('cuts a list longer than the contract carries, counts the rest and is no longer complete', async () => {
    const sources = Array.from({ length: 1_100 }, (_, i) => ({
      name: `s${String(i).padStart(4, '0')}`,
      type: 'quorum',
      arguments: {
        'x-dead-letter-exchange': 'dlx',
        'x-dead-letter-routing-key': 'dead',
      },
      policy: null,
      operator_policy: null,
      delivery_limit: 20,
    }));
    const { output } = await answerOf(
      { queue: 'dlq' },
      {
        exchanges: [{ name: 'dlx', type: 'direct' }],
        queues: [
          ...sources,
          {
            name: 'dlq',
            type: 'quorum',
            policy: null,
            operator_policy: null,
            delivery_limit: 20,
          },
        ],
        bindings: [{ source: 'dlx', destination: 'dlq', routing_key: 'dead' }],
      },
    );

    expect(output.sources).toHaveLength(1_000);
    expect(output.sourcesMore).toBe(100);
    expect(output.complete).toBe(false);
    expect(output.unknownReasons).toContainEqual({
      code: 'truncated',
      subject: 'sources',
    });
  });
});

describe('M1-20 AC-8 held x-death sources are passed through and echoed', () => {
  it('lists a held source that is not a known queue as possible, with an unknown limit', async () => {
    const { output } = await answerOf(
      { queue: 'orders.dlq', heldDeathSources: ['ghost', 'orders.q', 'ghost'] },
      SAMPLE_VHOST,
    );

    expect(output.heldDeathSourcesConsidered).toEqual(['ghost', 'orders.q']);
    expect(output.complete).toBe(false);
    expect(output.unknownReasons).toContainEqual({
      code: 'held-death-source-missing',
      subject: 'ghost',
    });
    const ghost = output.sources.find((s) => s.queue === 'ghost');
    expect(ghost).toMatchObject({
      certainty: 'possible',
      limit: { kind: 'unknown' },
    });
    expect(output.sources.find((s) => s.queue === 'orders.q')).toMatchObject({
      limit: { kind: 'finite', value: 20 },
    });
  });

  it('says nothing about x-death when none was passed', async () => {
    const { output } = await answerOf({ queue: 'orders.dlq' }, SAMPLE_VHOST);

    expect(output.heldDeathSourcesConsidered).toEqual([]);
    expect(output.complete).toBe(true);
  });

  it('gives a classic source no limit: unknown, and incomplete', async () => {
    const { output } = await answerOf(
      { queue: 'dlq' },
      {
        exchanges: [{ name: 'dlx', type: 'direct' }],
        queues: [
          {
            name: 'src',
            type: 'classic',
            arguments: {
              'x-dead-letter-exchange': 'dlx',
              'x-dead-letter-routing-key': 'dead',
              'x-message-ttl': 5_000,
            },
            policy: null,
            operator_policy: null,
          },
          {
            name: 'dlq',
            type: 'quorum',
            policy: null,
            operator_policy: null,
            delivery_limit: 20,
          },
        ],
        bindings: [{ source: 'dlx', destination: 'dlq', routing_key: 'dead' }],
      },
    );

    expect(output.sources).toMatchObject([
      { queue: 'src', limit: { kind: 'unknown' } },
    ]);
    expect(codes(output)).toEqual(['source-limit-unknown']);
    expect(output.complete).toBe(false);
  });

  it('refuses more held sources than the contract allows', async () => {
    await expect(
      answerOf(
        {
          queue: 'orders.dlq',
          heldDeathSources: Array.from(
            { length: 101 },
            (_, i) => `s${String(i)}`,
          ),
        },
        SAMPLE_VHOST,
      ),
    ).rejects.toMatchObject({ code: 'VALIDATION_FAILED' });
  });
});

describe('M1-20 AC-7 a policy match that cannot be decided makes the list incomplete', () => {
  it('adds the reason when two policies tie for an exchange', async () => {
    const tie = (name: string) => ({
      name,
      pattern: '.*',
      'apply-to': 'exchanges',
      priority: 0,
      definition: { 'alternate-exchange': 'orders.dlx' },
    });
    const { output } = await answerOf(
      { queue: 'orders.dlq' },
      { ...SAMPLE_VHOST, policies: [tie('a'), tie('b')] },
    );

    expect(output.complete).toBe(false);
    expect(output.gaps).toContain('policy-match-undecided');
    expect(output.unknownReasons).toContainEqual({
      code: 'policy-match-undecided',
    });
  });
});
